<?php if($kind==='plans'):$planned=0;$actual=0;foreach(LifePlanningService::rows('items')as $item)if($item['plan_id']===$record['id']){$planned+=$item['amount'];$actual+=$item['actual_amount'];} ?><p><?= e(t('Planned items')) ?> <?= money($planned) ?> <?= e(t('· Actual spending')) ?> <?= money($actual) ?> <?= e(t('· Budget remaining')) ?> <?= money($record['budget']-$actual) ?></p><?php endif; ?>
<?php if(in_array($kind,['plans','trips'],true)): ?><?php if($record['appointment_id']): ?><a href="/planner?view=appointments"><?= e(t('View linked calendar appointment')) ?></a><?php else: ?><form method="post" action="/life/manage/<?= e($kind) ?>/<?= e($record['id']) ?>/calendar"><?= csrf_field() ?><button class="secondary"><?= e(t('Link to calendar')) ?></button></form><?php endif; ?><?php endif; ?>
<?php if($kind==='seettu'):$s=LifePlanningReports::seettu($record); ?><p><?= e($s['rounds_due']) ?> <?= e(t('rounds due · Your paid contributions')) ?> <?= money($s['paid']) ?> <?= e(t('· Arrears')) ?> <?= money($s['arrears']) ?></p><?php endif; ?>
<?php if($kind==='metals'):$v=LifePlanningReports::metal($record); ?><p><?= $v?t('Estimated metal value ').e(money($v['value'])).' as of '.e($v['as_of']).' · '.e($v['source']):t('Enter a matching dated unit/purity price to calculate metal value.') ?></p><p class="muted"><?= e(t('This estimate excludes making charges and does not promise a resale price.')) ?></p><?php endif; ?>
<?php if($kind==='deposits'):$v=LifeFinanceMath::deposit($record); ?><p><?= e($v['days']) ?> <?= e(t('days · Gross interest')) ?> <?= money($v['gross_interest']) ?> <?= e(t('· Tax')) ?> <?= money($v['tax']) ?> <?= e(t('· Net interest')) ?> <?= money($v['net_interest']) ?> <?= e(t('· Maturity')) ?> <?= money($v['maturity']) ?> <?= e(t('· Annualized net')) ?> <?= e($v['annualized_percent']) ?>%</p><p class="muted"><?= e(t('Uses entered rates/fees, actual days and a 365-day year. No live market rate is assumed.')) ?></p><?php endif; ?>
<?php if($kind==='fx'): ?><p><?= e(t('Original')) ?> <?= e($record['code']) ?> <?= e($record['amount']) ?> <?= e(t('× saved rate')) ?> <?= e($record['rate_lkr']) ?> = <?= money($record['lkr_amount']) ?> <?= e(t('· Source:')) ?> <?= e($record['source']) ?></p><?php endif; ?>
<?php if($kind==='events'):$given=0;$received=0;$pending=0;foreach(LifePlanningService::rows('contributions')as $c)if($c['event_id']===$record['id']){if($c['paid_on']===null)$pending+=$c['amount'];elseif($c['direction']==='given')$given+=$c['amount'];else $received+=$c['amount'];} ?><p><?= e(t('Given')) ?> <?= money($given) ?> <?= e(t('· Received')) ?> <?= money($received) ?> <?= e(t('· Pending entries')) ?> <?= money($pending) ?></p><a href="/life?page=followups"><?= e(t('Plan a people follow-up')) ?></a><?php endif; ?>
<?php if(in_array($kind,['items','groceries'],true)&&module_enabled('Salary')): ?><?php if($record['expense_id']): ?><p><?= e(t('Linked Money expense #')) ?><?= e($record['expense_id']) ?><?= e(t('. Reverse it from Money before changing its cost.')) ?></p><?php else: ?><details><summary><?= e(t('Record actual cost in Money')) ?></summary><form class="form-grid" method="post" action="/life/manage/<?= e($kind) ?>/<?= e($record['id']) ?>/expense"><?= csrf_field() ?><label><?= e(t('Account')) ?><select name="account_id"><?php foreach(Db::all('SELECT id,name FROM accounts')as $a): ?><option value="<?= e($a['id']) ?>"><?= e($a['name']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Category')) ?><select name="category_id"><?php foreach(Db::all('SELECT id,name FROM expense_categories')as $a): ?><option value="<?= e($a['id']) ?>"><?= e($a['name']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Actual payment date')) ?><input type="date" name="date" required value="<?= e($record['actual_on']??$record['purchased_on']??ui_date('Y-m-d')) ?>"></label><button><?= e(t('Confirm one account debit')) ?></button></form></details><?php endif; ?><?php endif; ?>
<?php if($kind==='ingredients'): ?><form method="post" action="/life/ingredients/<?= e($record['id']) ?>/grocery"><?= csrf_field() ?><button class="secondary"><?= e(t('Add ingredient to grocery list')) ?></button></form><?php endif; ?>
<?php if($kind==='followups'&&$record['status']==='open'): ?><form method="post" action="/life/followups/<?= e($record['id']) ?>/task"><?= csrf_field() ?><button class="secondary"><?= e(t('Link a task for this occurrence')) ?></button></form><?php endif; ?>
<?php if($kind==='reminders'&&$record['status']==='active'||$kind==='followups'&&$record['status']==='open'):$path=$kind==='reminders'?'reminder':'followup'; ?><form method="post" action="/life/<?= e($path) ?>/<?= e($record['id']) ?>/done"><?= csrf_field() ?><input type="hidden" name="expected" value="<?= e($record[$kind==='reminders'?'next_on':'due_on']) ?>"><button class="secondary"><?= e(t('Complete this occurrence')) ?></button></form><?php endif; ?>
<?php if($kind==='loans'):$normal=LifeFinanceMath::amortization($record['principal'],$record['annual_rate'],$record['months']);$early=LifeFinanceMath::amortization($record['principal'],$record['annual_rate'],$record['months'],$record['early_month'],$record['early_amount'],$record['settlement_fee']); ?><p><?= e(t('Regular payment')) ?> <?= money($normal['scheduled_payment']) ?> <?= e(t('· Baseline interest')) ?> <?= money($normal['interest']) ?> <?= e(t('· With early payment interest')) ?> <?= money($early['interest']) ?> <?= e(t('+ settlement fees')) ?> <?= money($early['fees']) ?> <?= e(t('· Net savings')) ?> <?= money($normal['interest']-$early['interest']-$early['fees']) ?></p><details><summary><?= e(t('Amortization schedule')) ?></summary><div class="table-wrap"><table><tr><th><?= e(t('Month')) ?></th><th><?= e(t('Opening')) ?></th><th><?= e(t('Interest')) ?></th><th><?= e(t('Payment')) ?></th><th><?= e(t('Fee')) ?></th><th><?= e(t('Closing')) ?></th></tr><?php foreach($early['rows']as $line): ?><tr><?php foreach(['month','opening','interest','payment','fee','closing']as $col): ?><td><?= e($col==='month'?$line[$col]:number_format($line[$col],2)) ?></td><?php endforeach; ?></tr><?php endforeach; ?></table></div></details><?php endif; ?>
